package main

import (
	"fmt"
	"strings"
	"sync"

	"github.com/GopeedLab/gopeed/internal/fetcher"
	"github.com/GopeedLab/gopeed/pkg/base"
	"github.com/GopeedLab/gopeed/pkg/download"
	"github.com/GopeedLab/gopeed/pkg/protocol/http"
	"github.com/GopeedLab/gopeed/pkg/util"
)

const progressWidth = 20

func main() {
	args := parse()

	var wg sync.WaitGroup
	wg.Add(1)
	var checksumOpt *http.ChecksumOption
	if args.checksum != nil && *args.checksum != "" {
		algo := "md5"
		if args.checksumAlgo != nil && *args.checksumAlgo != "" {
			algo = *args.checksumAlgo
		}
		checksumOpt = &http.ChecksumOption{
			Algorithm: algo,
			Expected:  *args.checksum,
		}
	}

	_, err := download.Boot().
		URL(args.url).
		Listener(func(event *download.Event) {
			if event.Key == download.EventKeyProgress {
				printProgress(event.Task, "downloading...")
			}
			if event.Key == download.EventKeyFinally {
				var title string
				if event.Err != nil {
					title = "fail"
				} else {
					title = "complete"
				}
				printProgress(event.Task, title)
				fmt.Println()
				if event.Err != nil {
					fmt.Printf("reason: %s", event.Err.Error())
				} else {
					fmt.Printf("saving path: %s", *args.dir)
				}
				wg.Done()
			}
		}).
		Create(&base.Options{
			Path: *args.dir,
			Extra: http.OptsExtra{
				Connections: *args.connections,
				Checksum:    checksumOpt,
			},
		})
	if err != nil {
		panic(err)
	}
	printProgress(emptyTask, "downloading...")
	wg.Wait()
}

var (
	lastLineLen = 0
	sb          = new(strings.Builder)
	emptyTask   = &download.Task{
		Progress: &download.Progress{},
		Meta: &fetcher.FetcherMeta{
			Res: &base.Resource{},
		},
	}
)

func printProgress(task *download.Task, title string) {
	var rate float64
	if task.Meta.Res == nil {
		task = emptyTask
	}
	if task.Meta.Res.Size <= 0 {
		rate = 0
	} else {
		rate = float64(task.Progress.Downloaded) / float64(task.Meta.Res.Size)
	}
	completeWidth := int(progressWidth * rate)
	speed := util.ByteFmt(task.Progress.Speed)
	totalSize := util.ByteFmt(task.Meta.Res.Size)
	sb.WriteString(fmt.Sprintf("\r%s [", title))
	for i := 0; i < progressWidth; i++ {
		if i < completeWidth {
			sb.WriteString("■")
		} else {
			sb.WriteString("□")
		}
	}
	sb.WriteString(fmt.Sprintf("] %.1f%%    %s/s    %s", rate*100, speed, totalSize))
	if lastLineLen != 0 {
		paddingLen := lastLineLen - sb.Len()
		if paddingLen > 0 {
			sb.WriteString(strings.Repeat(" ", paddingLen))
		}
	}
	lastLineLen = sb.Len()
	fmt.Print(sb.String())
	sb.Reset()
}

package main

import (
	"flag"
	"fmt"
	"os"
)

type args struct {
	url          string
	connections  *int
	dir          *string
	checksum     *string
	checksumAlgo *string
}

func parse() *args {
	dir, err := os.Getwd()
	if err != nil {
		panic(err)
	}
	var args args
	args.connections = flag.Int("C", 16, "Concurrent connections.")
	args.dir = flag.String("D", dir, "Store directory.")
	args.checksum = flag.String("checksum", "", "Expected checksum hash (hex encoded).")
	args.checksumAlgo = flag.String("checksum-algo", "md5", "Checksum algorithm: md5, sha1, or sha256.")
	flag.Parse()
	t := flag.Args()
	if len(t) > 0 {
		args.url = t[0]
	} else {
		gPrintln("missing url parameter, for example: gopeed https://www.google.com or gopeed bt.torrent or gopeed magnet:?xt=urn:btih:...")
		gPrintln("try 'gopeed -h' for more information")
		os.Exit(1)
	}
	return &args
}

func gPrint(msg string) {
	fmt.Print("gopeed: " + msg)
}

func gPrintln(msg string) {
	gPrint(msg + "\n")
}

